#include <stdio.h>
int main(void) {
    int n, values[1000], target, answer = -1;
    if (scanf("%d", &n) != 1) return 0;
    for (int i = 0; i < n; i++) scanf("%d", &values[i]);
    scanf("%d", &target);
    for (int i = 0; i < n; i++) { if (values[i] == target) { answer = i; break; } }
    printf("%d\n", answer);
    return 0;
}

